window.JT_DATA={"firm":{"nameKr":"제이티 세무법인","nameEn":"JT TAX CORP.","address":"서울특별시 강남구 강남대로78길 22, 5층","addressEn":"22 Gangnam-daero 78-gil, Gangnam-gu, Seoul","phone":"02-554-6405","email":"jttax@jttax.co.kr","domain":"jttax.co.kr","kakaoSearchId":"","kakaoChannelUrl":"https://pf.kakao.com/_CcxlJG","kakaoChatUrl":"https://pf.kakao.com/_CcxlJG","kakaoFriendUrl":"https://pf.kakao.com/_CcxlJG","kakaoMapUrl":"https://place.map.kakao.com/1776119720","naverMapUrl":"https://map.naver.com/p/entry/place/1319293073","googleMapUrl":"https://www.google.com/maps/search/?api=1&query=%EC%84%9C%EC%9A%B8%20%EA%B0%95%EB%82%A8%EB%8C%80%EB%A1%9C78%EA%B8%B8%2022%205%EC%B8%B5","businessNumber":"","licenseNumber":"","representative":"김민석·이현준·김가환","adAccountant":"이현준","businessHours":"평일 09:30–17:30","responseSla":"문의 확인 후 진행 방법 안내"},"integrations":{"web3formsKey":"c3a5ab0f-c275-4434-a4ba-bda8500378fa","ga4MeasurementId":"","naverSiteVerification":"","googleSiteVerification":""},"seo":{"siteUrl":"https://www.jttax.co.kr","titleDefault":"제이티 세무법인 — 강남 세무상담","titleTemplate":"%s | 제이티 세무법인","description":"서울 강남에 위치한 제이티 세무법인입니다. 세무기장·세금 신고부터 양도·상속·증여, 기업 자문과 세무조사 대응까지 함께 살핍니다.","ogImage":"https://www.jttax.co.kr/project/assets/og-image.png?v=2","keywords":"강남 세무사, 기장, 세금 신고, 양도소득세, 상속세, 증여세, 기업 세무 자문, 세무조사 대응, 경정청구, 제이티 세무법인","pageMeta":{"home":{"titleFull":"제이티 세무법인 — 강남 세무상담","desc":"서울 강남에 위치한 제이티 세무법인입니다. 세무기장·세금 신고부터 양도·상속·증여, 기업 자문과 세무조사 대응까지 함께 살핍니다."},"services":{"title":"업무분야 — 사업과 재산의 세무","desc":"기장·신고, 양도·상속·증여, 기업 자문, 세무조사 대응과 경정청구를 안내합니다."},"team":{"title":"대표세무사 소개","desc":"카카오톡 상담은 대표가 직접 받고, 모든 신고는 대표가 직접 검토합니다. 김민석·이현준·김가환 대표세무사를 소개합니다."},"about":{"title":"회사소개 — 제이티 세무법인","desc":"사업과 재산의 세금 문제를 근거와 문서로 살피는 제이티 세무법인을 소개합니다."},"insights":{"title":"세금 가이드 — 신고·계산·상담 전 확인할 사항","desc":"세무조사·상속·증여·법인 실무에서 자주 부딪히는 쟁점을 정리합니다."},"report":{"title":"세금 계산기 — 양도소득세·증여세·상속세 등","desc":"양도소득세·증여세·상속세 등 예상 세금과 4대보험을 계산하고, 개인사업자·법인 및 증여 방법별 세금을 비교해 보세요. 결과는 입력 조건에 따른 참고 자료입니다."},"contact":{"title":"상담 안내 — 연락 방법·준비 자료·오시는 길","desc":"전화·카카오톡·온라인 신청 방법과 상담 절차, 준비 자료를 안내합니다. 방문 상담은 사전 예약해 주세요."},"booking":{"title":"상담 신청 — 필요한 분야와 연락처 남기기","desc":"상담 분야와 상황, 연락처를 남겨 주세요. 접수 내용을 확인한 뒤 검토 범위와 보수를 안내합니다."},"report:cgt":{"title":"양도소득세 계산기","desc":"집·부동산을 팔 때. 1세대1주택 비과세·일시적2주택·입주권·장기보유특별공제·다주택 중과까지 검증 엔진으로 계산."},"report:gift":{"title":"증여세 계산기","desc":"관계·금액·부담부증여·10년 합산까지. 부동산은 주소로 공시가격을 조회해 증여세를 계산합니다."},"report:inheritance":{"title":"상속세 계산기","desc":"배우자·자녀 공제, 채무·장례비·금융재산공제와 10년 내 사전증여 합산까지 반영해 상속세를 계산합니다."},"report:acquisition":{"title":"취득세 계산기","desc":"살 때(매매·증여·상속·신축). 다주택 중과·조정지역·생애최초 감면·농특세·지방교육세까지 계산."},"report:property":{"title":"재산세 계산기","desc":"집·건물·토지 보유 시 매년 내는 재산세. 공시가격·1세대1주택 특례·도시지역분·세부담 상한까지."},"report:comprehensive":{"title":"종합부동산세 계산기","desc":"6월 1일 기준 주택 공시 합계. 1세대1주택 12억·연령·보유 세액공제·다주택 중과·재산세 공제까지."},"report:income":{"title":"종합소득세 계산기","desc":"사업·프리랜서·근로 소득을 합산해 종합소득세를 계산. 인적공제·자녀·연금저축 세액공제까지 반영."},"report:vat":{"title":"부가가치세 계산기","desc":"일반·간이과세자 매출·매입으로 낼 부가세(또는 환급액)를 즉시 계산. 매입세액·신용카드 공제와 신고기한까지 안내."},"report:compare":{"title":"처분방법 비교 — 증여 vs 매매 vs 상속","desc":"같은 부동산을 자녀에게 팔까·증여할까·상속할까. 세 방법의 증여세·양도세·상속세·취득세를 한 번에 비교(세액만). 실제 적용은 사실관계와 자료를 확인한 뒤 판단합니다."},"report:burden":{"title":"부담부증여 계산기","desc":"자녀·배우자에게 부동산을 증여할 때 딸린 채무(전세·대출)를 함께 넘기면 세금이 얼마나 달라지는지 — 실제 채무 금액 범위 안에서 증여세+양도세+취득세를 계산해 세액 차이를 보여 줍니다. 실제 실행 여부는 채무와 거래 내용을 확인한 뒤 판단합니다."},"report:corporate":{"title":"개인사업자·법인 세금 비교","desc":"개인사업자 이익과 대표 연봉으로 개인(종합소득세)과 법인(법인세+대표 급여 근로소득세) 세부담을 바로 비교."},"report:insurance":{"title":"월급 실수령액 계산기","desc":"세전 월급으로 국민연금·건강보험·장기요양·고용보험과 세금을 떼고 실수령액을 즉시 계산(2026년 요율)."},"report:appeal":{"title":"경정청구 환급 진단","desc":"입력한 내용으로 경정청구 검토가 필요한 항목을 살펴봅니다. 환급 여부는 신고 내역과 증빙 확인이 필요합니다."}}},"services":[{"num":"01","en":"LEGACY","kr":"양도·상속·증여","slug":"asset-transfer","short":"자산 이전 전 과정의 세무 설계.","desc":"가족 관계와 자산, 이전 시기를 확인하고 증여·상속·양도에 따른 세금을 비교합니다. 선택에 필요한 근거와 신고 준비 사항을 설명합니다.","points":[{"b":"사전 증여 설계","s":"기존 증여 내역과 이전 시기를 반영한 세액 비교"},{"b":"상속 신고·집행","s":"상속재산 가액 평가, 공제 적용 검토, 분할 협의 지원"},{"b":"양도소득세 검토","s":"장특공제·1세대 1주택·비사업용 토지 판정"},{"b":"가업승계 컨설팅","s":"가업상속공제·증여특례 요건 검토 및 사후관리"}]},{"num":"02","en":"AUDIT","kr":"세무조사 대응","slug":"tax-audit","short":"조사 통지부터 불복까지, 일관된 전략.","desc":"조사 통지 단계부터 쟁점을 정리해 소명 논리를 세웁니다. 조문·판례·심판례로 근거를 갖춰 대응합니다.","points":[{"b":"사전 리스크 진단","s":"신고 내역·거래 증빙과 예상 쟁점 검토"},{"b":"현장 대응","s":"질문서·소명자료 작성, 조사관 면담 동석"},{"b":"조세불복·심판청구","s":"이의신청·심사·심판청구의 사유와 절차 검토"},{"b":"경정청구","s":"과세관청의 처분을 바로잡는 납세자 권리 행사"}]},{"num":"03","en":"BOOKKEEPING","kr":"세무기장·세금 신고","slug":"bookkeeping","short":"법인·개인의 월간 세무 운영.","desc":"매월 거래와 증빙을 정리하고 장부를 바탕으로 결산·부가세·원천세·법인세 등 필요한 신고 업무를 확인하고 관리합니다.","points":[{"b":"법인 기장 대행","s":"매월 전표 기장·결산·법인세 신고"},{"b":"개인사업자·프리랜서","s":"종합소득세·부가가치세 신고 및 공제 검토"},{"b":"원천세·4대보험","s":"급여·퇴직·용역 원천 관리"},{"b":"크리에이터·인플루언서","s":"유튜버·방송·온라인 수익 구조 맞춤 신고"}]},{"num":"04","en":"CONSULTING","kr":"세금 종합 컨설팅","slug":"consulting","short":"의사결정 이전의 세무 시뮬레이션.","desc":"법인 전환이나 자산 이전을 고민하고 계신가요? 현재 구조와 계획을 확인하고, 선택지별 세 부담과 실행 전에 확인할 사항을 비교합니다.","points":[{"b":"법인 전환 검토","s":"개인사업자의 법인 전환 시점·구조 분석"},{"b":"주주·지분 재구성","s":"명의신탁 해소·가지급금·자본거래 정리"},{"b":"부동산 임대 구조","s":"공동명의·법인 소유·임대사업자 비교"},{"b":"스타트업 세무","s":"투자 유치·스톡옵션·전환사채 세무 실무"}]},{"num":"05","en":"APPEAL","kr":"경정청구","slug":"tax-refund","short":"이미 낸 세금, 돌려받는 권리.","desc":"이미 낸 세금에 공제 누락이나 계산 오류가 있는지 살핍니다. 신고 내역과 청구 기한을 확인하고, 검토할 사유가 있으면 필요한 자료와 절차를 안내합니다.","points":[{"b":"환급 가능 사유 진단","s":"청구 기한과 합의한 범위의 신고 내역 검토"},{"b":"양도·상속·증여 경정","s":"평가 오류·공제 누락 재산정"},{"b":"부가세 경정","s":"매입세액 누락·면세·영세율 적용 오류"},{"b":"법인세 경정","s":"손금 불산입·세액공제 누락 재신고"}]},{"num":"06","en":"ACQUISITION TAX","kr":"취득세","href":"/acquisition-tax/","short":"취득할 때의 세율·감면, 이미 낸 취득세의 재검토.","desc":"집·건물·토지를 취득할 때 세대·주택 수·취득 시기·감면 요건에 따라 세율이 갈립니다. 취득 전에는 계산기와 상황별 안내 글로 확인하고, 이미 낸 취득세는 서류를 보고 다시 볼 여지가 있는지 점검합니다.","points":[{"b":"취득세 계산기","s":"주택 수·조정대상지역·전용면적과 입력한 감면 종류로 세액을 참고 계산합니다(감면 요건의 충족 여부는 판정하지 않습니다)"},{"b":"감면 요건 확인","s":"생애최초·출산·양육 등 조문이 정한 요건과 사후관리"},{"b":"이미 낸 취득세 1차 재검토","s":"써 주신 내용만으로 다시 볼 여지가 있는지 확인하는 접수 — 서류는 수임 뒤에 받습니다"},{"b":"경정청구·불복","s":"5년·90일의 기한과 절차를 먼저 확인하고, 다시 볼 여지가 있으면 경정청구·불복으로 이어집니다"}]},{"num":"07","en":"CREATORS","kr":"유튜버·크리에이터 세무","href":"/creators.html","short":"유튜버·인플루언서의 정산부터 팀 운영까지.","desc":"크리에이터의 세금은 단계마다 쟁점이 다릅니다. 첫 정산을 받은 사람, 직장을 다니며 겸업하는 사람, 팀·MCN으로 커지는 사람의 세 경로로 나눠 사업자등록·기장·신고를 안내합니다.","points":[{"b":"첫 정산","s":"사업자등록 시점과 종합소득세·부가가치세 신고"},{"b":"직장 겸업","s":"근로소득과 사업소득이 함께 있을 때의 신고"},{"b":"팀·MCN 운영","s":"인건비·외주비 처리와 법인 전환 검토"},{"b":"월 기장","s":"플랫폼 수익 구조에 맞춘 장부와 신고"}]}]};
